# use saved exact Zhang-Suen skeleton and compute distance map for target threshold
from PIL import Image
import numpy as np, heapq, math
from scipy.ndimage import distance_transform_edt
im=np.asarray(Image.open('/app/target.png').convert('L'))
b=im<130; a=np.load('/app/output/skeleton.npy')
# make path using left/right endpoints in component crop
ys,xs=np.where(a);
def deg(y,x):return sum(1 for dy in (-1,0,1) for dx in (-1,0,1) if (dy or dx) and 0<=y+dy<a.shape[0] and 0<=x+dx<a.shape[1] and a[y+dy,x+dx])
ep=[(int(y),int(x)) for y,x in zip(ys,xs) if deg(int(y),int(x))==1]
st=min(ep,key=lambda p:p[1]);en=max(ep,key=lambda p:p[1]); d={st:0};pre={};q=[(0,st)]
while q:
 dd,p=heapq.heappop(q)
 if dd!=d[p]:continue
 if p==en:break
 y,x=p
 for dy in (-1,0,1):
  for dx in (-1,0,1):
   t=(y+dy,x+dx)
   if (dy or dx) and 0<=t[0]<a.shape[0] and 0<=t[1]<a.shape[1] and a[t]:
    nd=dd+math.hypot(dx,dy)
    if nd<d.get(t,1e9):d[t]=nd;pre[t]=p;heapq.heappush(q,(nd,t))
p=en;path=[p]
while p!=st:p=pre[p];path.append(p)
path.reverse(); coords=np.array([(x+140,y+475) for y,x in path],float)
dt=distance_transform_edt(b[475:565,140:875]);r=np.array([dt[y-475,x-140] for x,y in coords])
# smooth radii for class grouping using moving avg
rsm=np.convolve(r,np.ones(15)/15,'same')
s=np.r_[0,np.cumsum(np.linalg.norm(np.diff(coords,axis=0),axis=1))]
for thresh in [1.5,1.8,2.2,2.6,3.0]:
 zones=[]; prev=False;start=None
 for i,v in enumerate(rsm>thresh):
  if v and not prev:start=i
  if prev and not v:zones.append((start,i-1))
  prev=v
 if prev:zones.append((start,len(rsm)-1))
 print('\nthresh',thresh)
 for i,j in zones:
  if s[j]-s[i]>8: print(' %.1f px: (%.0f,%.0f)->(%.0f,%.0f), radius %.1f..%.1f'% (s[j]-s[i],*coords[i],*coords[j],rsm[i:j+1].min(),rsm[i:j+1].max()))
print('path length px',s[-1],'samples',len(coords))
